-- ============================================================
-- STAYJOGJA SUPABASE DATABASE SCHEMA & DATA MIGRATION
-- Generated: 2026-10-03T13:46:16.399Z
-- ============================================================

-- 1. DROP EXISTING TABLES (IF ANY) IN PROPER DEPENDENCY ORDER
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS reservations CASCADE;
DROP TABLE IF EXISTS units CASCADE;
DROP TABLE IF EXISTS properties CASCADE;
DROP TABLE IF EXISTS tourist_spots CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- ============================================================
-- 2. CREATE TABLES
-- ============================================================

-- 2.1 USERS TABLE
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'user', -- 'user', 'owner', 'admin'
    phone TEXT,
    address TEXT,
    status TEXT DEFAULT 'active',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2.2 PROPERTIES TABLE
CREATE TABLE properties (
    id TEXT PRIMARY KEY,
    owner_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    name TEXT NOT NULL,
    type TEXT NOT NULL, -- 'hotel', 'homestay', 'apartemen'
    stars INTEGER DEFAULT 0,
    address TEXT NOT NULL,
    area TEXT NOT NULL,
    postal_code TEXT,
    description TEXT,
    rating NUMERIC(3,1) DEFAULT 4.8,
    review_count INTEGER DEFAULT 0,
    facilities JSONB DEFAULT '[]'::jsonb,
    photos JSONB DEFAULT '[]'::jsonb,
    contact_pic JSONB DEFAULT '{}'::jsonb,
    payout_info JSONB DEFAULT '{}'::jsonb,
    status_approval TEXT DEFAULT 'approved', -- 'pending', 'approved', 'rejected'
    rejection_reason TEXT,
    deletion_requested BOOLEAN DEFAULT FALSE,
    deletion_reason TEXT,
    deletion_requested_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2.3 UNITS (ROOMS) TABLE
CREATE TABLE units (
    id TEXT PRIMARY KEY,
    property_id TEXT REFERENCES properties(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    price NUMERIC NOT NULL,
    available_stock INTEGER DEFAULT 1,
    capacity INTEGER DEFAULT 2,
    bed_type TEXT,
    room_size NUMERIC,
    facilities JSONB DEFAULT '[]'::jsonb,
    photos JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2.4 RESERVATIONS TABLE
CREATE TABLE reservations (
    id TEXT PRIMARY KEY,
    booking_code TEXT UNIQUE NOT NULL,
    user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    property_id TEXT REFERENCES properties(id) ON DELETE CASCADE,
    unit_id TEXT REFERENCES units(id) ON DELETE CASCADE,
    property_name TEXT,
    unit_name TEXT,
    guest_name TEXT NOT NULL,
    guest_email TEXT NOT NULL,
    guest_phone TEXT NOT NULL,
    guest_nik TEXT,
    check_in DATE NOT NULL,
    check_out DATE NOT NULL,
    nights INTEGER DEFAULT 1,
    guests_count INTEGER DEFAULT 1,
    total_price NUMERIC NOT NULL,
    status TEXT DEFAULT 'menunggu_pembayaran', -- 'menunggu_pembayaran', 'menunggu_acc', 'terkonfirmasi', 'ditolak', 'checked_in', 'selesai', 'dibatalkan'
    payment_status TEXT DEFAULT 'unpaid', -- 'unpaid', 'paid', 'refunded'
    payment_method TEXT,
    payment_transaction_id TEXT,
    paid_at TIMESTAMPTZ,
    rejection_reason TEXT,
    checked_in_at TIMESTAMPTZ,
    invoice_number TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2.5 TOURIST SPOTS TABLE (FOR AI CHATBOT & EXPLORATION)
CREATE TABLE tourist_spots (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL, -- 'wisata', 'kuliner'
    area TEXT NOT NULL,
    description TEXT,
    distance TEXT,
    image TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2.6 NOTIFICATIONS TABLE
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    property_name TEXT,
    read BOOLEAN DEFAULT FALSE,
    timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- ============================================================
-- 3. INDEXES FOR PERFORMANCE
-- ============================================================
CREATE INDEX idx_properties_type ON properties(type);
CREATE INDEX idx_properties_area ON properties(area);
CREATE INDEX idx_properties_stars ON properties(stars);
CREATE INDEX idx_properties_status ON properties(status_approval);
CREATE INDEX idx_units_property ON units(property_id);
CREATE INDEX idx_units_price ON units(price);
CREATE INDEX idx_reservations_code ON reservations(booking_code);
CREATE INDEX idx_reservations_user ON reservations(user_id);
CREATE INDEX idx_reservations_prop ON reservations(property_id);
CREATE INDEX idx_reservations_status ON reservations(status);

-- ============================================================
-- 4. ROW LEVEL SECURITY (RLS) POLICIES
-- ============================================================
-- Enable RLS
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE properties ENABLE ROW LEVEL SECURITY;
ALTER TABLE units ENABLE ROW LEVEL SECURITY;
ALTER TABLE reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE tourist_spots ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

-- Allow public read for catalog & spots
CREATE POLICY "Public properties are viewable by everyone" ON properties FOR SELECT USING (true);
CREATE POLICY "Public units are viewable by everyone" ON units FOR SELECT USING (true);
CREATE POLICY "Public spots are viewable by everyone" ON tourist_spots FOR SELECT USING (true);
CREATE POLICY "Public notifications are viewable by everyone" ON notifications FOR SELECT USING (true);

-- Allow full access for service_role / backend API
CREATE POLICY "Service role has full access to users" ON users FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Service role has full access to properties" ON properties FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Service role has full access to units" ON units FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Service role has full access to reservations" ON reservations FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Service role has full access to tourist_spots" ON tourist_spots FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Service role has full access to notifications" ON notifications FOR ALL USING (true) WITH CHECK (true);

