INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-001', 'Jalan Malioboro & Tugu Jogja', 'wisata', 'Malioboro / Pusat Kota', 'Pusat ikonik belanja cinderamata, pedestrian budaya, musisi jalanan, dan spot foto khas Yogyakarta.', 'Sekitar 300m - 1km dari area Malioboro', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-002', 'Kraton Ngayogyakarta Hadiningrat', 'wisata', 'Malioboro / Pusat Kota', 'Istana resmi Kesultanan Ngayogyakarta dengan arsitektur Jawa klasik adiluhung dan museum pusaka.', '1.5 km dari Malioboro', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-003', 'Tamansari Water Castle', 'wisata', 'Prawirotaman / Selatan', 'Situs bekas pemandian dan benteng peristirahatan sultan dengan lorong bawah tanah dan masjid sumur gumuling yang estetik.', '1 km dari Prawirotaman', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-004', 'Kampung Turis Prawirotaman', 'wisata', 'Prawirotaman / Selatan', 'Pusat kafe santai, galeri seni, toko buku vintage, dan penginapan bernuansa tropis kosmopolitan.', 'Tepat di area Prawirotaman', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-005', 'Candi Prambanan & Ratu Boko', 'wisata', 'Sleman / Timur', 'Kompleks candi Hindu terbesar di Indonesia warisan UNESCO dengan pertunjukan sendratari Ramayana spektakuler.', '15 km ke arah timur Jogja', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-006', 'Kaliurang & Merapi Lava Tour', 'wisata', 'Sleman / Kaliurang', 'Kawasan sejuk lereng Gunung Merapi dengan atraksi off-road Jeep Lava Tour, Bunker Kaliadem, dan Museum Gunung Merapi.', '22 km ke arah utara', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-007', 'Gudeg Yu Djum Wijilan 167', 'kuliner', 'Malioboro / Pusat Kota', 'Gudeg kering legendaris sejak tahun 1950 dengan ayam kampung bumbu areh pekat dan telur bebek khas Wijilan.', '800m dari Kraton / Malioboro', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-008', 'Warung Kopi Klotok & Pisang Goreng', 'kuliner', 'Sleman / Kaliurang', 'Sensasi makan khas pedesaan Jogja dengan sayur lodeh kluwih, telur krispi dadar, kopi tubruk klotok, dan pisang goreng hangat.', 'Dekat Jl. Kaliurang KM 16', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-009', 'Sate Klatak Pak Pong', 'kuliner', 'Bantul / Selatan', 'Sate kambing muda khas Jejeran Bantul yang dibakar dengan jeruji besi sepeda motor, hanya dibumbui garam dan disajikan kuah gulai gurih.', '8 km dari pusat kota Jogja', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-010', 'Oseng Mercon Bu Narti', 'kuliner', 'Malioboro / Pusat Kota', 'Kuliner malam pedas ekstrem berisi oseng koyor daging sapi dengan puluhan cabai rawit pedas meledak di lidah.', '1 km barat Malioboro (Jl. KH Ahmad Dahlan)', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-011', 'Tempo Gelato Prawirotaman', 'kuliner', 'Prawirotaman / Selatan', 'Kedai gelato Italia otentik bernuansa industrial vintage dengan pilihan rasa lokal seperti rempah, kemangi, hingga matcha dan cokelat pekat.', 'Jl. Prawirotaman No. 43', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO tourist_spots (id, name, category, area, description, distance, image) VALUES ('spot-012', 'Angkringan Kopi Joss Lik Man', 'kuliner', 'Malioboro / Pusat Kota', 'Angkringan legendaris di dekat Stasiun Tugu dengan sajian khas kopi panas yang dicelup arang membara (kopi joss) dan nasi kucing.', '300m utara Stasiun Tugu Malioboro', NULL) ON CONFLICT (id) DO NOTHING;
